// StaticGrow1SaveAt is engine's whole state at the macrostep boundary it
// stands at: every variable, the machine's own included, and where it stands, as
// the `sce-saved-state` document every backend reads (sce.SavedState.ToJSON).
// Each delayed `<send>` still waiting is written as the moment it comes due on
// the wall clock whose reading now is wallNowMs, in milliseconds since the Unix
// epoch.
//
// Refused for a machine that is not running, one that has ended, one whose last
// macrostep stopped at the microstep ceiling, and one built around another
// document's policy.
func StaticGrow1SaveAt(engine *sce.Engine[StaticGrow1State, StaticGrow1Event], wallNowMs int64) (*sce.SavedState, error) {
	p, ok := engine.Policy().(*StaticGrow1Policy)
	if !ok {
		return nil, sce.Refuse("the engine is not one of StaticGrow1")
	}
	variables := sce.NewJSONObject()
	variables.Set("outer", optional.Wire(p.vOuter, func(v StaticGrow1OuterRecord) any { return v.ToSaved() }))
	variables.Set("kept", p.vKept.ToSaved())
	variables.Set("many", sce.SavedWriteList(p.vMany, func(r StaticGrow1ItemRecord) any { return r.ToSaved() }))
	variables.Set("maybe", optional.Wire(p.vMaybe, func(v StaticGrow1InnerRecord) any { return v.ToSaved() }))
	variables.Set("shape", p.vShape.ToSaved())
	var children []sce.SavedChild
	return sce.SaveSession(engine, &StaticGrow1SavedShape, variables,
		sce.SaveHistory[StaticGrow1State, StaticGrow1Event](p, StaticGrow1Histories),
		children, wallNowMs)
}

// StaticGrow1Save is StaticGrow1SaveAt at the host's wall clock now.
func StaticGrow1Save(engine *sce.Engine[StaticGrow1State, StaticGrow1Event]) (*sce.SavedState, error) {
	return StaticGrow1SaveAt(engine, sce.SavedWallClockMs())
}

// StaticGrow1Judge refuses saved unless a machine of this document could
// restore it, building nothing: what a parent's restore asks of each child it
// holds (docs/adr/0045, section 3, step 1).
func StaticGrow1Judge(saved *sce.SavedState) error {
	p := &StaticGrow1Policy{}
	grown, err := sce.UpgradeSavedState(saved, &StaticGrow1SavedShape)
	if err != nil {
		return err
	}
	if _, err := sce.RestoreHistory[StaticGrow1State, StaticGrow1Event](p, grown, StaticGrow1Histories); err != nil {
		return err
	}
	if raw, err := grown.Variable("outer"); err != nil {
		return err
	} else if _, err := sce.SavedReadOptional(raw, "outer", StaticGrow1OuterRecordFromSaved, optional.None[StaticGrow1OuterRecord], optional.Some[StaticGrow1OuterRecord]); err != nil {
		return err
	}
	if raw, err := grown.Variable("kept"); err != nil {
		return err
	} else if _, err := StaticGrow1InnerRecordFromSaved(raw, "kept"); err != nil {
		return err
	}
	if raw, err := grown.Variable("many"); err != nil {
		return err
	} else if _, err := sce.SavedReadList(raw, "many", 2, StaticGrow1ItemRecordFromSaved); err != nil {
		return err
	}
	if raw, err := grown.Variable("maybe"); err != nil {
		return err
	} else if _, err := sce.SavedReadOptional(raw, "maybe", StaticGrow1InnerRecordFromSaved, optional.None[StaticGrow1InnerRecord], optional.Some[StaticGrow1InnerRecord]); err != nil {
		return err
	}
	if raw, err := grown.Variable("shape"); err != nil {
		return err
	} else if _, err := StaticGrow1GrowShape1UnionFromSaved(raw, "shape"); err != nil {
		return err
	}
	return sce.JudgeSession[StaticGrow1State, StaticGrow1Event](p, grown)
}

// StaticGrow1RestoreAt is a machine of policy standing where saved left
// one, measuring time by clock: in place of `Initialize`, so no `<onentry>` runs
// and no `<data>` is evaluated, since the saved run already did both. Every value
// is read and the state judged before any is written, so a refused restore leaves
// policy as it was.
//
// Each delayed `<send>` saved is armed against clock, which is the one the
// machine measures time by; wallNowMs is what time it is on the wall clock the
// saved `due`s were written against. A send comes due when its saved moment does,
// and one already due comes due now.
//
// The host registers its invokers and its processors on the machine this
// returns, and drives it as it would one it had initialized.
func StaticGrow1RestoreAt(policy *StaticGrow1Policy, saved *sce.SavedState, clock sce.SceClock, wallNowMs int64) (*sce.Engine[StaticGrow1State, StaticGrow1Event], error) {
	// The state as one of this machine: each record saved at an earlier revision
	// of its schema holds the defaults of the fields added since.
	grown, err := sce.UpgradeSavedState(saved, &StaticGrow1SavedShape)
	if err != nil {
		return nil, err
	}
	history, err := sce.RestoreHistory[StaticGrow1State, StaticGrow1Event](policy, grown, StaticGrow1Histories)
	if err != nil {
		return nil, err
	}
	raw1, err := grown.Variable("outer")
	if err != nil {
		return nil, err
	}
	read1, err := sce.SavedReadOptional(raw1, "outer", StaticGrow1OuterRecordFromSaved, optional.None[StaticGrow1OuterRecord], optional.Some[StaticGrow1OuterRecord])
	if err != nil {
		return nil, err
	}
	raw2, err := grown.Variable("kept")
	if err != nil {
		return nil, err
	}
	read2, err := StaticGrow1InnerRecordFromSaved(raw2, "kept")
	if err != nil {
		return nil, err
	}
	raw3, err := grown.Variable("many")
	if err != nil {
		return nil, err
	}
	read3, err := sce.SavedReadList(raw3, "many", 2, StaticGrow1ItemRecordFromSaved)
	if err != nil {
		return nil, err
	}
	raw4, err := grown.Variable("maybe")
	if err != nil {
		return nil, err
	}
	read4, err := sce.SavedReadOptional(raw4, "maybe", StaticGrow1InnerRecordFromSaved, optional.None[StaticGrow1InnerRecord], optional.Some[StaticGrow1InnerRecord])
	if err != nil {
		return nil, err
	}
	raw5, err := grown.Variable("shape")
	if err != nil {
		return nil, err
	}
	read5, err := StaticGrow1GrowShape1UnionFromSaved(raw5, "shape")
	if err != nil {
		return nil, err
	}
	if err := sce.JudgeSession[StaticGrow1State, StaticGrow1Event](policy, grown); err != nil {
		return nil, err
	}
	policy.vOuter = read1
	policy.vKept = read2
	policy.vMany = read3
	policy.vMaybe = read4
	policy.vShape = read5
	for _, recorded := range history {
		policy.SetHistoryValue(recorded.History, recorded.States)
	}
	return sce.EnterSession[StaticGrow1State, StaticGrow1Event](policy, grown, clock, wallNowMs)
}

// StaticGrow1Restore is StaticGrow1RestoreAt at the host's wall
// clock now.
func StaticGrow1Restore(policy *StaticGrow1Policy, saved *sce.SavedState, clock sce.SceClock) (*sce.Engine[StaticGrow1State, StaticGrow1Event], error) {
	return StaticGrow1RestoreAt(policy, saved, clock, sce.SavedWallClockMs())
}

